css:
/* Summit Ridge type and buttons, from handoff "Home Page Variant 2".
   Headings are wide, bold and uppercase; eyebrows are small spaced capitals; buttons are dark with white text. */
.bz-block :is(h1, h2, h3) { text-transform: uppercase; letter-spacing: -0.005em; }
.bz-block h1 { font-size: clamp(34px, 5vw, var(--text-h1)); line-height: 1.05; }
.bz-block h2 { font-size: clamp(26px, 3.4vw, var(--text-h2)); line-height: 1.1; }
.bz-eyebrow { font: 700 var(--text-eyebrow) / 1.4 var(--font-body); letter-spacing: .16em; color: var(--muted); }
.bz-section--bg-ink .bz-eyebrow { color: rgba(255,255,255,.8); }
.bz-btn { font: 700 13px / 1 var(--font-heading); text-transform: uppercase; letter-spacing: .02em; padding: 15px 22px; border-radius: var(--radius-input); }
.bz-btn--primary { color: #fff; }
.bz-btn--secondary { background: #fff; color: var(--ink); border-color: #fff; }
.bz-btn--link { text-decoration: none; text-transform: none; font: 700 15px / 1 var(--font-body); color: var(--ink); letter-spacing: 0; }
.bz-btn--link:hover { text-decoration: underline; }
.bz-btn--on-dark.bz-btn--link { color: #fff; }
.bz-input { border-radius: var(--radius-input); border-color: var(--line); }

/* A stacked row keeps its 12 grid tracks, so a wide gap between them can push the page wider than a phone. Cap it. */
@media (max-width: 640px) { .bz-row { column-gap: min(var(--bz-gap, 24px), 12px); } }
